// Throwaway OCR smoke run: same prompt and images for every model, scored against fixtures/manifest.json.
import { readFile, writeFile } from "node:fs/promises";

const [fixturesDir, outFile] = process.argv.slice(2);
const KEY = process.env.GEMINI_API_KEY;
const MODELS = ["gemma-4-26b-a4b-it", "gemma-4-31b-it", "gemini-3.8-flash"];

const PROMPT = `You are reading a photo of a gravestone for a historical research tool.

Transcribe ONLY what is carved or cast on the stone. Do NOT add, guess, or complete anything you cannot see.

Return ONLY a JSON object, no prose, no code fences:
{"text": string|null, "people": [{"name": string, "born": string|null, "died": string|null}]}

- text: every line of the inscription in order, joined with "\\n". Write "[?]" for a word you cannot read. null if nothing is legible.
- people: one entry per person commemorated. name exactly as carved. born/died as "YYYY" or "YYYY-MM-DD"; use "?" for an unreadable digit; null when the date is not on the stone. [] if no name is legible.
- A year that is not a birth or death (marriage length, erection date) is NOT a life date.`;

const norm = (s) => (s ?? "").toLowerCase().replace(/[^\p{L}\p{N}?]+/gu, " ").trim();

function lev(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}

function textScore(expected, got) {
  const e = norm(expected), g = norm(got);
  if (!e) return g ? 0 : 1;
  return Math.max(0, 1 - lev(e, g) / e.length);
}

function peopleScore(expected, got) {
  if (!expected.length) return { fields: got.length ? 0 : 1, total: 1, correct: got.length ? 0 : 1, extra: got.length };
  let correct = 0, total = 0;
  const pool = [...got];
  for (const p of expected) {
    const i = pool.findIndex((q) => norm(q.name) === norm(p.name));
    const q = i >= 0 ? pool.splice(i, 1)[0] : null;
    for (const k of ["name", "born", "died"]) {
      total++;
      if (q && (q[k] ?? null) === (p[k] ?? null)) correct++;
    }
  }
  return { correct, total, extra: pool.length };
}

async function call(model, img) {
  const t0 = performance.now();
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-goog-api-key": KEY },
    body: JSON.stringify({
      contents: [{ role: "user", parts: [{ inline_data: { mime_type: "image/jpeg", data: img } }, { text: PROMPT }] }],
      generationConfig: { temperature: 0 },
    }),
  });
  const ms = Math.round(performance.now() - t0);
  const body = await res.json();
  if (!res.ok) return { ms, error: `${res.status} ${body.error?.message ?? ""}`.slice(0, 200) };
  const raw = (body.candidates?.[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? "").join("");
  const usage = body.usageMetadata ?? {};
  const json = raw.slice(raw.indexOf("{"), raw.lastIndexOf("}") + 1);
  try {
    return { ms, parsed: JSON.parse(json), raw, inTok: usage.promptTokenCount, outTok: (usage.candidatesTokenCount ?? 0) + (usage.thoughtsTokenCount ?? 0) };
  } catch {
    return { ms, error: "unparseable JSON", raw };
  }
}

const manifest = JSON.parse(await readFile(`${fixturesDir}/manifest.json`, "utf8"));
const results = [];
for (const f of manifest) {
  const img = (await readFile(`${fixturesDir}/${f.file}`)).toString("base64");
  for (const model of MODELS) {
    const r = await call(model, img);
    const row = { file: f.file, era: f.era, model, ms: r.ms, inTok: r.inTok, outTok: r.outTok, error: r.error, got: r.parsed, raw: r.error ? r.raw : undefined };
    if (r.parsed) {
      row.text = textScore(f.text, r.parsed.text);
      Object.assign(row, peopleScore(f.people, Array.isArray(r.parsed.people) ? r.parsed.people : []));
    }
    results.push(row);
    console.error(`${f.file.padEnd(26)} ${model.padEnd(20)} ${r.error ? "ERR " + r.error : `text ${row.text.toFixed(2)} fields ${row.correct}/${row.total} extra ${row.extra} ${r.ms}ms`}`);
  }
}
await writeFile(outFile, JSON.stringify(results, null, 2));

