// Run 2: system prompt + JSON schema + Gemma-recommended sampling. Hosted models via Gemini API, `ollama:` models locally.
import { readFile, writeFile } from "node:fs/promises";

const [fixturesDir, outFile, ...models] = process.argv.slice(2);
const P = JSON.parse(await readFile(new URL("./prompt2.json", import.meta.url), "utf8"));

async function hosted(model, img) {
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-goog-api-key": process.env.GEMINI_API_KEY },
    body: JSON.stringify({
      systemInstruction: { parts: [{ text: P.system }] },
      contents: [{ role: "user", parts: [{ inline_data: { mime_type: "image/jpeg", data: img } }, { text: P.user }] }],
      generationConfig: { ...P.sampling, responseMimeType: "application/json", responseJsonSchema: P.schema },
    }),
    signal: AbortSignal.timeout(240_000),
  });
  const body = await res.json();
  if (!res.ok) throw new Error(`${res.status} ${body.error?.message ?? ""}`.slice(0, 200));
  return (body.candidates?.[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? "").join("");
}

async function ollama(model, img) {
  const res = await fetch("http://127.0.0.1:11434/api/chat", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      model, stream: false, think: false, format: P.schema,
      options: { temperature: P.sampling.temperature, top_p: P.sampling.topP, top_k: P.sampling.topK },
      messages: [{ role: "system", content: P.system }, { role: "user", content: P.user, images: [img] }],
    }),
    signal: AbortSignal.timeout(240_000),
  });
  const body = await res.json();
  if (!res.ok) throw new Error(`${res.status} ${body.error ?? ""}`);
  return body.message.content;
}

const manifest = JSON.parse(await readFile(`${fixturesDir}/manifest.json`, "utf8"));
const results = [];
for (const f of manifest) {
  const img = (await readFile(`${fixturesDir}/${f.file}`)).toString("base64");
  for (const model of models) {
    const t0 = performance.now();
    const row = { file: f.file, model };
