// Usage: node benchmarks/run.ts <prompt.json> <out.json> <model...>
// Hosted model names go to the Gemini API; `ollama:<name>` runs locally.
import { readFile, writeFile } from 'node:fs/promises';

interface Prompt {
	system?: string;
	user: string;
	sampling: { temperature: number; topP?: number; topK?: number };
	schema?: object;
}

interface Row {
	file: string;
	model: string;
	ms: number;
	got?: unknown;
	error?: string;
	raw?: string;
}

const [promptPath, outFile, ...models] = process.argv.slice(2);
const fixturesDir = new URL('../fixtures/', import.meta.url);
const P: Prompt = JSON.parse(await readFile(promptPath, 'utf8'));

/**
 * Calls a hosted model on the Gemini API.
 * @param model Gemini API model name.
 * @param img Base64 JPEG.
 * @returns The reply text with thought parts removed.
 * @throws On a non-2xx response or timeout.
 */
async function hosted(model: string, img: string): Promise<string> {
	const res = await fetch(
		`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
		{
			method: 'POST',
			headers: { 'content-type': 'application/json', 'x-goog-api-key': process.env.GEMINI_API_KEY ?? '' },
			body: JSON.stringify({
				...(P.system && { systemInstruction: { parts: [{ text: P.system }] } }),
				contents: [
					{ role: 'user', parts: [{ inline_data: { mime_type: 'image/jpeg', data: img } }, { text: P.user }] }
				],
				generationConfig: {
					...P.sampling,
					...(P.schema && { responseMimeType: 'application/json', responseJsonSchema: P.schema })
				}
			}),
			signal: AbortSignal.timeout(240_000)
		}
	);
	const body = await res.json();
	if (!res.ok) throw new Error(`${res.status} ${body.error?.message ?? ''}`.slice(0, 200));
	const parts: { text?: string; thought?: boolean }[] = body.candidates?.[0]?.content?.parts ?? [];
	return parts
		.filter((p) => !p.thought)
		.map((p) => p.text ?? '')
		.join('');
}

/**
 * Calls a local model through Ollama with thinking off.
 * @param model Ollama model tag.
 * @param img Base64 JPEG.
 * @returns The reply text.
 * @throws On a non-2xx response or timeout.
 */
async function ollama(model: string, img: string): Promise<string> {
	const { temperature, topP, topK } = P.sampling;
	const res = await fetch('http://127.0.0.1:11434/api/chat', {
		method: 'POST',
		headers: { 'content-type': 'application/json' },
		body: JSON.stringify({
			model,
			stream: false,
			think: false,
			format: P.schema,
			options: { temperature, top_p: topP, top_k: topK },
			messages: [
				...(P.system ? [{ role: 'system', content: P.system }] : []),
				{ role: 'user', content: P.user, images: [img] }
			]
		}),
		signal: AbortSignal.timeout(240_000)
	});
	const body = await res.json();
	if (!res.ok) throw new Error(`${res.status} ${body.error ?? ''}`);
	return body.message.content;
}

/**
 * Parses a reply. Schema replies must be pure JSON; prose-format replies are cut to the outermost braces.
 * @param raw Reply text.
 * @returns The parsed object.
 * @throws SyntaxError when the reply is not valid JSON.
 */
function parse(raw: string): unknown {
	return JSON.parse(P.schema ? raw : raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
}

const manifest: { file: string }[] = JSON.parse(await readFile(new URL('manifest.json', fixturesDir), 'utf8'));
const results: Row[] = [];
for (const { file } of manifest) {
	const img = (await readFile(new URL(file, fixturesDir))).toString('base64');
	for (const model of models) {
		const t0 = performance.now();
		const row: Row = { file, model, ms: 0 };
		let raw = '';
		try {
			raw = model.startsWith('ollama:') ? await ollama(model.slice(7), img) : await hosted(model, img);
			row.got = parse(raw);
		} catch (e) {
			const err = e as Error;
			row.error = err.name === 'SyntaxError' ? 'unparseable JSON' : `${err.name}: ${err.message}`;
			if (raw) row.raw = raw;
		}
		row.ms = Math.round(performance.now() - t0);
		results.push(row);
		await writeFile(outFile, JSON.stringify(results, null, 2));
		console.error(`${file.padEnd(24)} ${model.padEnd(22)} ${row.error ?? 'ok'} ${row.ms}ms`);
	}
}

// Usage: node benchmarks/score.ts <results.json...>
// Prints a markdown table per fixture and model. Rows for fixtures no longer in the manifest are skipped.
import { readFile } from 'node:fs/promises';

interface Person {
	name: string | null;
	born: string | null;
	died: string | null;
}

interface Fixture {
	file: string;
	text: string | null;
	people: Person[];
}

interface Row {
	file: string;
	model: string;
	ms: number;
	got?: { text?: string | null; people?: Partial<Person>[] };
	error?: string;
}

const HONORIFICS = new Set(['mr', 'mrs', 'miss', 'dr']);

/**
 * Lowercases and collapses everything except letters, digits and `?` to single spaces.
 * @param s Text to normalize.
 * @returns Normalized text.
 */
function norm(s: string | null | undefined): string {
	return (s ?? '')
		.toLowerCase()
		.replace(/[^\p{L}\p{N}?]+/gu, ' ')
		.trim();
}

/**
 * Levenshtein edit distance.
 * @param a First string.
 * @param b Second string.
 * @returns Number of single-character edits.
 */
function lev(a: string, b: string): number {
	let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
	for (let i = 1; i <= a.length; i++) {
		const cur = [i];
		for (let j = 1; j <= b.length; j++)
			cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)));
		prev = cur;
	}
	return prev[b.length];
}

/**
 * Scores transcription similarity.
 * @param expected Ground-truth inscription; null when illegible.
 * @param got Model transcription.
 * @returns 1 − distance / expected length, floored at 0.
 */
function textScore(expected: string | null, got: string | null | undefined): number {
	const e = norm(expected);
	const g = norm(got);
	if (!e) return g ? 0 : 1;
	return Math.max(0, 1 - lev(e, g) / e.length);
}

/**
 * Turns a name into comparable ASCII tokens without honorifics.
 * @param name Name as returned or recorded.
 * @returns Lowercase tokens.
 */
function nameTokens(name: string | null | undefined): string {
	return (name ?? '')
		.toLowerCase()
		.replace('m.r', 'mr')
		.replace(/[^a-z0-9 ]+/g, ' ')
		.split(/\s+/)
		.filter((t) => t && !HONORIFICS.has(t))
		.join(' ');
}

/**
 * Counts correct name/born/died fields. A wrong name zeroes that person's dates.
 * @param expected Ground-truth people.
 * @param got People the model returned.
 * @returns Correct and total field counts.
 */
function peopleScore(expected: Person[], got: Partial<Person>[]): { correct: number; total: number } {
	if (!expected.length) return { correct: got.length ? 0 : 1, total: 1 };
	const pool = [...got];
	let correct = 0;
	for (const p of expected) {
		const i = pool.findIndex((q) => nameTokens(q.name) === nameTokens(p.name));
		const q = i >= 0 ? pool.splice(i, 1)[0] : null;
		if (!q) continue;
		correct += 1 + Number((q.born ?? null) === p.born) + Number((q.died ?? null) === p.died);
	}
	return { correct, total: expected.length * 3 };
}

const manifest: Fixture[] = JSON.parse(
	await readFile(new URL('../fixtures/manifest.json', import.meta.url), 'utf8')
);
const byFile = new Map(manifest.map((f) => [f.file, f]));
const rows: Row[] = [];
for (const path of process.argv.slice(2)) rows.push(...JSON.parse(await readFile(path, 'utf8')));

const agg = new Map<string, { calls: number; ms: number; errors: number; text: number; correct: number; total: number }>();
const cells = new Map<string, string>();
for (const r of rows) {
	const f = byFile.get(r.file);
	if (!f) continue;
	const a = agg.get(r.model) ?? { calls: 0, ms: 0, errors: 0, text: 0, correct: 0, total: 0 };
	agg.set(r.model, a);
	a.calls++;
	a.ms += r.ms;
	if (r.error || !r.got) {
		a.errors++;
		cells.set(`${r.file}|${r.model}`, r.error?.includes('Timeout') ? 'timeout' : 'bad JSON');
		continue;
	}
	a.text += textScore(f.text, r.got.text);
	const s = peopleScore(f.people, Array.isArray(r.got.people) ? r.got.people : []);
	a.correct += s.correct;
	a.total += s.total;
	cells.set(`${r.file}|${r.model}`, `${s.correct}/${s.total}`);
}

const models = [...agg.keys()];
const stats = [...agg.values()];
const line = (cols: string[]) => console.log(`| ${cols.join(' | ')} |`);
line(['Fixture', ...models]);
line(['---', ...models.map(() => '---')]);
for (const f of manifest) line([f.file.replace(/\.jpg$/, ''), ...models.map((m) => cells.get(`${f.file}|${m}`) ?? '-')]);
line([
	'**Fields correct**',
	...stats.map((a) => `**${a.correct}/${a.total} (${Math.round((100 * a.correct) / a.total)}%)**`)
]);
line(['Text similarity', ...stats.map((a) => `${((100 * a.text) / (a.calls - a.errors)).toFixed(1)}%`)]);
line(['Errors', ...stats.map((a) => String(a.errors))]);
line(['Avg time per photo', ...stats.map((a) => `${(a.ms / a.calls / 1000).toFixed(1)} s`)]);

